begin;
with j as (select * from jsonb_to_recordset($law7d0018$[{"code_id":"APK_RF","article_number":"312","version_date":"2002-07-24","article_text":"В случае, если наличие обстоятельства, предусмотренного пунктом 5 части 3 статьи 311 настоящего Кодекса, выявлено при рассмотрении кассационных жалобы, представления или надзорных жалобы, представления, указанный трехмесячный срок исчисляется со дня размещения определения об отказе в передаче кассационных жалобы, представления для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации, определения об отказе в передаче надзорных жалобы, представления для рассмотрения в судебном заседании Президиума Верховного Суда Российской Федерации в информационно-телекоммуникационной сети \"Интернет\".\n\n(Часть в редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n(Статья в редакции Федерального закона от 23.12.2010 № 379-ФЗ)","article_title":"Статья 312. Порядок и срок подачи заявления о пересмотре судебного акта по новым или вновь открывшимся обстоятельствам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"358dbe801bb4e7bf019835d9a664d3b731c9f095b25c82a4132c03edaceb8c6b"},{"code_id":"APK_RF","article_number":"313","version_date":"2002-07-24","article_text":"1) наименование арбитражного суда, в который подается заявление;\n\n2) наименования лица, подающего заявление, и других лиц, участвующих в деле, их адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n3) наименование арбитражного суда, принявшего судебный акт, о пересмотре которого по новым или вновь открывшимся обстоятельствам ходатайствует заявитель; номер дела, дата принятия судебного акта; предмет спора; (В редакции Федерального закона от 23.12.2010 № 379-ФЗ)\n\n4) требование лица, подающего заявление; новое или вновь открывшееся обстоятельство, предусмотренное статьей 311 настоящего Кодекса и являющееся, по мнению заявителя, основанием для постановки вопроса о пересмотре судебного акта по новым или вновь открывшимся обстоятельствам, со ссылкой на документы, подтверждающие открытие или установление этого обстоятельства; (В редакции Федерального закона от 23.12.2010 № 379-ФЗ)\n\n5) перечень прилагаемых документов.\n\nВ заявлении могут быть также указаны номера телефонов, факсов, адреса электронной почты лиц, участвующих в деле, и иные сведения.\n\nЗаявление и прилагаемые к нему документы в электронном виде направляются лицам, участвующим в деле, посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. (Дополнение абзацем - Федеральный закон от 30.12.2021 № 440-ФЗ)\n\n1) копии документов, подтверждающих новые или вновь открывшиеся обстоятельства; (В редакции Федерального закона от 23.12.2010 № 379-ФЗ)\n\n2) копия судебного акта, о пересмотре которого ходатайствует заявитель;\n\n3) документ, подтверждающий направление другим лицам, участвующим в деле, копий заявления и документов, которые у них отсутствуют;\n\n4) доверенность или иной документ, подтверждающие полномочия лица на подписание заявления.","article_title":"Статья 313. Форма и содержание заявления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"89aeb638564b63f433bd1c373da5b897e1b67830cddeed75d95e36c19d86e984"},{"code_id":"APK_RF","article_number":"314","version_date":"2002-07-24","article_text":"В случае нарушения указанных требований арбитражный суд возвращает заявление в порядке, предусмотренном статьей 315 настоящего Кодекса.\n\nО принятии заявления к производству арбитражный суд выносит определение.\n\nВ определении указываются время и место проведения судебного заседания по рассмотрению заявления.\n\nКопии определения направляются лицам, участвующим в деле.","article_title":"Статья 314. Принятие заявления к производству арбитражного суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4c3d2d96b661a01e2aaccd4ce21cc6b02618679f4ab392dc8d0a4039e7663732"},{"code_id":"APK_RF","article_number":"315","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 23.12.2010 № 379-ФЗ)\n\n1) заявление подано с нарушением правил, установленных статьей 310 настоящего Кодекса;\n\n2) заявление подано после истечения установленного срока и отсутствует ходатайство о его восстановлении или в восстановлении пропущенного срока подачи заявления отказано;\n\n3) не соблюдены требования, предъявляемые настоящим Кодексом к форме и содержанию заявления.\n\nКопия определения направляется заявителю вместе с заявлением и прилагаемыми к нему документами не позднее следующего дня после дня его вынесения.","article_title":"Статья 315. Возвращение заявления о пересмотре судебного акта по новым или вновь открывшимся обстоятельствам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b6deee67f48c2baa0ac768b9113cb57fc1a0cac40b318f6e8d5d9ad62699192b"},{"code_id":"APK_RF","article_number":"316","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 23.12.2010 № 379-ФЗ)","article_title":"Статья 316. Рассмотрение заявления о пересмотре судебного акта по новым или вновь открывшимся обстоятельствам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1d0f26d9b6abb45c695dda3a2053fda3aafcd29f2e6544ccde517cdd3020fc91"},{"code_id":"APK_RF","article_number":"317","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 23.12.2010 № 379-ФЗ)\n\nьи 311 настоящего Кодекса, судебный акт, принятый в результате повторного рассмотрения дела, не может быть изменен в сторону ухудшения положения лица, привлекаемого или привлеченного к ответственности за административные или налоговые правонарушения либо к иной публично-правовой ответственности. (Дополнение частью - Федеральный закон от 23.12.2010 № 379-ФЗ)\n\nРАЗДЕЛ VII. ПРОИЗВОДСТВО ПО ДЕЛАМ, СВЯЗАННЫМ С ИСПОЛНЕНИЕМ СУДЕБНЫХ АКТОВ АРБИТРАЖНЫХ СУДОВ","article_title":"Статья 317. Судебные акты, принимаемые арбитражным судом по результатам рассмотрения заявления о пересмотре судебного акта по новым или вновь открывшимся обстоятельствам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8099bf47a67e9501f2839b93fb63e7646f872577331ca1174bcad718fc9bce21"},{"code_id":"APK_RF","article_number":"318","version_date":"2002-07-24","article_text":"1. Судебные акты арбитражных судов приводятся в исполнение после вступления их в законную силу, за исключением случаев немедленного исполнения, в порядке, установленном настоящим Кодексом и иными федеральными законами, регулирующими вопросы исполнительного производства.\n\n2. Принудительное исполнение судебного акта производится на основании выдаваемого арбитражным судом исполнительного листа, если иное не предусмотрено настоящим Кодексом.","article_title":"Статья 318. Порядок исполнения судебных актов арбитражных судов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8b22e2ce2a73047d7ba372553523631cd7b3fbc27a5178240b6cf0aef8af1ecb"},{"code_id":"APK_RF","article_number":"319","version_date":"2002-07-24","article_text":"Выдача судебного приказа для исполнения осуществляется по правилам, предусмотренным главой 291 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 02.03.2016 № 47-ФЗ)\n\n(Часть в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\nИсполнительный лист по решению о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок направляется на исполнение арбитражным судом в пятидневный срок со дня принятия решения независимо от наличия ходатайства об этом взыскателя. (Дополнение абзацем - Федеральный закон от 30.04.2010 № 69-ФЗ)\n\nИсполнительный лист может направляться судом для исполнения в форме электронного документа, подписанного судьей усиленной квалифицированной электронной подписью в порядке, установленном законодательством Российской Федерации. (Дополнение абзацем - Федеральный закон от 08.03.2015 № 41-ФЗ)","article_title":"Статья 319. Выдача исполнительного листа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2795503fcb7b5e289b946df5819a4479899817b68a92b1f3153a2e859d4c181c"},{"code_id":"APK_RF","article_number":"32","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\nАрбитражные суды рассматривают в соответствии с главой 31 настоящего Кодекса дела о признании и приведении в исполнение решений иностранных судов и иностранных арбитражных решений по спорам, возникающим при осуществлении предпринимательской и иной экономической деятельности.","article_title":"Статья 32. Компетенция арбитражных судов по делам о признании и приведении в исполнение решений иностранных судов и иностранных арбитражных решений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2df625eac5856743686c53e3e73d705c79adc7d0dc7ac0fc548e62b2527a688b"},{"code_id":"APK_RF","article_number":"320","version_date":"2002-07-24","article_text":"1. В исполнительном листе должны быть указаны:\n\n1) наименование арбитражного суда, выдавшего исполнительный лист; наименование и место нахождения иностранного суда, третейского суда или международного коммерческого арбитража, если исполнительный лист выдан арбитражным судом на основании решения такого суда;\n\n2) дело, по которому выдан исполнительный лист, и номер дела;\n\n3) дата принятия судебного акта, подлежащего исполнению;\n\n4) сведения о взыскателе: для гражданина-взыскателя - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, серия и номер водительского удостоверения); для организации-взыскателя - наименование, адрес, идентификационный номер налогоплательщика; сведения о должнике: для гражданина-должника - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, место работы (если известно), один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, основной государственный регистрационный номер индивидуального предпринимателя, серия и номер водительского удостоверения); для организации-должника - наименование, адрес, идентификационный номер налогоплательщика и основной государственный регистрационный номер; (В редакции Федерального закона от 21.12.2021 № 417-ФЗ)\n\n5) резолютивная часть судебного акта;\n\n6) дата вступления судебного акта в законную силу либо требование о его немедленном исполнении; (В редакции Федерального закона от 02.10.2007 № 225-ФЗ)\n\n7) дата выдачи исполнительного листа и срок предъявления его к исполнению;\n\n8) реквизиты банковского счета взыскателя, на который должны быть перечислены средства, подлежащие взысканию, в случае присуждения компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок. (Дополнение пунктом - Федеральный закон от 30.04.2010 № 69-ФЗ) (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\nЕсли до выдачи исполнительного листа арбитражным судом предоставлена отсрочка или рассрочка исполнения судебного акта, в исполнительном листе указывается, с какого времени начинается течение срока действия исполнительного листа.\n\n2. Исполнительный лист подписывается судьей и заверяется гербовой печатью арбитражного суда.","article_title":"Статья 320. Содержание исполнительного листа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"71d9bd2d72ba770f5bb34971eb3b503191e352070a59fb3343b6badfe6e25910"},{"code_id":"APK_RF","article_number":"321","version_date":"2002-07-24","article_text":"1. Исполнительный лист может быть предъявлен к исполнению в следующие сроки:\n\n1) в течение трех лет со дня вступления судебного акта в законную силу, или со следующего дня после дня принятия судебного акта, подлежащего немедленному исполнению, или со дня окончания срока, установленного при отсрочке или рассрочке исполнения судебного акта;\n\n2) в течение трех месяцев со дня вынесения определения о восстановлении пропущенного срока для предъявления исполнительного листа к исполнению в соответствии со статьей 322 настоящего Кодекса.\n\n2. В случае, если исполнение судебного акта было приостановлено, время, на которое исполнение приостанавливалось, не засчитывается в срок, установленный для предъявления исполнительного листа к исполнению.\n\n3. Срок предъявления исполнительного листа к исполнению прерывается предъявлением его к исполнению, если федеральным законом не установлено иное, частичным исполнением судебного акта.\n\n4. В случае возвращения исполнительного листа взыскателю в связи с невозможностью его исполнения новый срок для предъявления исполнительного листа к исполнению исчисляется со дня его возвращения.","article_title":"Статья 321. Сроки предъявления исполнительного листа к исполнению","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1d639f2a6589ab9228bfb5b9de526e2416aa08679f1edc0ebda0ae6316be6677"},{"code_id":"APK_RF","article_number":"322","version_date":"2002-07-24","article_text":"1. Взыскатель, пропустивший срок для предъявления исполнительного листа к исполнению, вправе обратиться в арбитражный суд первой инстанции, рассматривавший дело, с заявлением о восстановлении пропущенного срока, если восстановление указанного срока предусмотрено федеральным законом.\n\n2. Заявление взыскателя о восстановлении пропущенного срока рассматривается в порядке, предусмотренном статьей 117 настоящего Кодекса. По результатам рассмотрения заявления выносится определение.\n\nКопии определения направляются взыскателю и должнику.\n\n3. Определение арбитражного суда по вопросу о восстановлении пропущенного срока для предъявления исполнительного листа к исполнению может быть обжаловано.","article_title":"Статья 322. Восстановление пропущенного срока для предъявления исполнительного листа к исполнению","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aba707f6aa43260c0bf276c2ff714f511d8b4be5430601d49a5ddea2d157dca1"},{"code_id":"APK_RF","article_number":"324","version_date":"2002-07-24","article_text":"1. При наличии обстоятельств, затрудняющих исполнение судебного акта, арбитражный суд, выдавший исполнительный лист, по заявлению взыскателя, должника или судебного пристава-исполнителя вправе отсрочить или рассрочить исполнение судебного акта, изменить способ и порядок его исполнения.\n\n2. Заявление об отсрочке или о рассрочке исполнения судебного акта, об изменении способа и порядка его исполнения рассматривается арбитражным судом в месячный срок со дня поступления заявления в арбитражный суд в судебном заседании с извещением взыскателя, должника и судебного пристава-исполнителя. Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием для рассмотрения заявления.\n\nПо результатам рассмотрения заявления выносится определение.\n\nКопии определения направляются взыскателю, должнику и судебному приставу-исполнителю.\n\n3. В случае предоставления должнику отсрочки или рассрочки исполнения судебного акта арбитражный суд вправе по заявлению взыскателя принять меры по обеспечению исполнения судебного акта по правилам, установленным главой 8 настоящего Кодекса.\n\n4. Определение арбитражного суда об отсрочке или о рассрочке исполнения судебного акта, об изменении способа и порядка его исполнения либо об отказе в удовлетворении заявления об отсрочке или о рассрочке исполнения судебного акта, об изменении способа и порядка его исполнения может быть обжаловано.","article_title":"Статья 324. Отсрочка или рассрочка исполнения судебного акта, изменение способа и порядка его исполнения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"81561a7284bf3b4af27b3acc2cd4db9098e9c7a9656948882d717fc34db07e14"},{"code_id":"APK_RF","article_number":"325","version_date":"2002-07-24","article_text":"1. Если приведенный в исполнение судебный акт отменен полностью или в части и принят новый судебный акт о полном или частичном отказе в иске, либо иск оставлен без рассмотрения, либо производство по делу прекращено, ответчику возвращается все то, что было взыскано с него в пользу истца по отмененному или измененному в соответствующей части судебному акту.\n\n2. Если не приведенный в исполнение судебный акт отменен полностью или в части и принят новый судебный акт о полном или частичном отказе в иске, либо иск оставлен без рассмотрения полностью или в части, либо производство по делу прекращено, арбитражный суд принимает судебный акт о полном или частичном прекращении взыскания по отмененному в соответствующей части судебному акту.","article_title":"Статья 325. Поворот исполнения судебного акта","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"02729b18cd77192440f380fd0f76b48ebc6004fcc05d8926a5c91d00220f4b92"},{"code_id":"APK_RF","article_number":"326","version_date":"2002-07-24","article_text":"1. Вопрос о повороте исполнения судебного акта разрешается арбитражным судом, принявшим новый судебный акт, которым отменен или изменен ранее принятый судебный акт.\n\n2. Если в постановлении об отмене или изменении судебного акта нет указаний на поворот его исполнения, ответчик вправе подать соответствующее заявление в арбитражный суд первой инстанции.\n\n3. Заявление о повороте исполнения судебного акта рассматривается в порядке, предусмотренном статьей 324 настоящего Кодекса.\n\n4. Определение арбитражного суда о повороте исполнения судебного акта или об отказе в повороте исполнения может быть обжаловано.\n\n5. Арбитражный суд первой инстанции выдает исполнительный лист на возврат взысканных денежных средств, имущества или его стоимости по заявлению организации, гражданина. К заявлению прилагается документ, подтверждающий исполнение ранее принятого судебного акта.","article_title":"Статья 326. Разрешение вопроса о повороте исполнения судебного акта","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ba87dde823901f1d6661377e798253e9d706c14abf3e210389518611e371c8bb"},{"code_id":"APK_RF","article_number":"327","version_date":"2002-07-24","article_text":"1. Арбитражный суд по заявлению взыскателя, должника, судебного пристава-исполнителя может приостановить, возобновить или прекратить исполнительное производство, возбужденное Федеральной службой судебных приставов в автоматическом режиме или судебным приставом-исполнителем на основании исполнительного листа, выданного арбитражным судом, в случаях, предусмотренных федеральным законом об исполнительном производстве.\n\nЗаявление о возобновлении приостановленного исполнительного производства может быть подано лицами, указанными в настоящей части, в течение трех лет с момента устранения обстоятельств, послуживших основанием для его приостановления.\n\n2. Пропущенный по уважительной причине срок подачи заявления о возобновлении исполнительного производства может быть восстановлен судом на основании ходатайства взыскателя, должника, судебного пристава-исполнителя. Указанное ходатайство рассматривается в порядке, предусмотренном статьей 117 настоящего Кодекса.\n\n3. Приостановление, возобновление или прекращение исполнительного производства производится арбитражным судом, выдавшим исполнительный лист, либо арбитражным судом по месту нахождения судебного пристава-исполнителя, в том числе ведущего исполнительное производство, решение о возбуждении которого принято Федеральной службой судебных приставов в автоматическом режиме.\n\n4. Заявление о приостановлении, возобновлении или прекращении исполнительного производства рассматривается в десятидневный срок со дня поступления такого заявления в суд в порядке, предусмотренном статьей 324 настоящего Кодекса.\n\n5. Определение арбитражного суда о приостановлении, возобновлении или прекращении исполнительного производства либо об отказе в удовлетворении заявления о приостановлении, возобновлении или прекращении исполнительного производства может быть обжаловано.\n\n(Статья в редакции  Федерального закона от 06.04.2024 № 74-ФЗ)","article_title":"Статья 327. Приостановление, возобновление или прекращение исполнительного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"00416a031f535272b799f344c6152a7f7dd6616befb9737d56f0174fc3782ddd"},{"code_id":"APK_RF","article_number":"328","version_date":"2002-07-24","article_text":"1. При наличии обстоятельств, препятствующих совершению отдельных исполнительных действий, арбитражный суд по заявлению взыскателя, должника или судебного пристава-исполнителя может отложить исполнительные действия по исполнительному производству, возбужденному на основании исполнительного листа, выданного арбитражным судом.\n\n2. Отложение исполнительных действий производится арбитражным судом, выдавшим исполнительн\n\nый лист, или арбитражным судом по месту нахождения судебного пристава-исполнителя.3. Заявление об отложении исполнительных действий рассматривается арбитражным судом в десятидневный срок в порядке, предусмотренном статьей 324 настоящего Кодекса.По результатам рассмотрения заявления суд выносит определение.4. В определении об отложении исполнительных действий указывается дата, до которой откладываются исполнительные действия, или событие, наступление которого является основанием для возобновления судебным приставом-исполнителем исполнительных действий.Копии определения об отложении исполнительных действий направляются взыскателю, должнику и судебному приставу-исполнителю.Статья 329. Оспаривание постановлений должностных лиц службы судебных приставов, их действий (бездействия)1. Постановления главного судебного пристава Российской Федерации, главного судебного пристава субъекта (главного судебного пристава субъектов) Российской Федерации, старшего судебного пристава, их заместителей, судебного пристава-исполнителя, их действия (бездействие) могут быть оспорены в арбитражном суде в случаях, предусмотренных настоящим Кодексом и другими федеральными законами, по правилам, установленным главой 24 настоящего Кодекса. (В редакции Федерального закона от 30.12.2015 № 425-ФЗ)2. Заявление об оспаривании постановлений должностных лиц службы судебных приставов, их действий (бездействия) государственной пошлиной не облагается.(Статья в редакции Федерального закона от 02.10.2007 № 225-ФЗ)Статья 330. Ответственность за неисполнение или ненадлежащее исполнение судебным приставом-исполнителем своих обязанностей1. Вред, причиненный судебным приставом-исполнителем в результате неисполнения или ненадлежащего исполнения своих обязанностей по исполнению исполнительного листа, выданного арбитражным судом, подлежит возмещению в порядке, предусмотренном гражданским законодательством.2. Требование о возмещении вреда рассматривается арбитражным судом по общим правилам искового производства, предусмотренным настоящим Кодексом.Статья 331. Ответственность за утрату исполнительного листаНа лицо, виновное в утрате переданного ему на исполнение исполнительного листа, выданного арбитражным судом, арбитражный суд вправе наложить судебный штраф в порядке и в размере, установленных в главе 11 настоящего Кодекса.Статья 332. Ответственность за неисполнение судебного акта(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)1. За неисполнение судебного акта арбитражного суда органами государственной власти, органами местного самоуправления, иными органами, организациями, должностными лицами и гражданами арбитражным судом может быть наложен судебный штраф по правилам главы 11 настоящего Кодекса в размере, установленном федеральным законом. (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)2. За неисполнение указанных в исполнительном листе действий лицом, на которое возложено совершение этих действий, на это лицо арбитражным судом, выдавшим исполнительный лист, может быть наложен судебный штраф в порядке и в размере, установленных в главе 11 настоящего Кодекса.3. Уплата судебного штрафа не освобождает от обязанности исполнить судебный акт.4. Вопрос о наложении судебного штрафа рассматривается арбитражным судом по заявлению взыскателя или судебного пристава-исполнителя в порядке, установленном настоящим Кодексом.Президент Российской Федерации                              В.ПутинМосква, Кремль24 июля 2002 года№ 95-ФЗ\n\nый лист, или арбитражным судом по месту нахождения судебного пристава-исполнителя.\n\n3. Заявление об отложении исполнительных действий рассматривается арбитражным судом в десятидневный срок в порядке, предусмотренном статьей 324 настоящего Кодекса.\n\nПо результатам рассмотрения заявления суд выносит определение.\n\n4. В определении об отложении исполнительных действий указывается дата, до которой откладываются исполнительные действия, или событие, наступление которого является основанием для возобновления судебным приставом-исполнителем исполнительных действий.\n\nКопии определения об отложении исполнительных действий направляются взыскателю, должнику и судебному приставу-исполнителю.","article_title":"Статья 328. Отложение исполнительных действий","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"33e16b6c35f092c1a687b0aec497c455a6ec17b473af3dcd155005e54f9200a6"},{"code_id":"APK_RF","article_number":"329","version_date":"2002-07-24","article_text":"(Статья в редакции Федерального закона от 02.10.2007 № 225-ФЗ)","article_title":"Статья 329. Оспаривание постановлений должностных лиц службы судебных приставов, их действий (бездействия)","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d7bad72b1538e2cade1fe1222ddc9df2988b260076e433e140df7a08379842fc"},{"code_id":"APK_RF","article_number":"33","version_date":"2002-07-24","article_text":"1) споры, предусмотренные пунктами 1, 3, 6 части 6 статьи 27 настоящего Кодекса;\n\n2) споры, предусмотренные разделом III настоящего Кодекса;\n\n3) споры, предусмотренные главами 27, 271 и 282 настоящего Кодекса;\n\n4) споры, предусмотренные пунктами 1 - 5 части 2 статьи 2251 настоящего Кодекса;\n\n5) споры, возникающие из отношений, регулируемых законодательством Российской Федерации о приватизации государственного и муниципального имущества;\n\n6) споры, возникающие из отношений, регулируемых законодательством Российской Федерации о контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд;\n\n7) споры, возникающие из отношений, связанных с возмещением вреда, причиненного окружающей среде;\n\n8) иные споры в случаях, прямо предусмотренных федеральным законом.\n\n(Статья в редакции Федерального закона от 29.12.2015 № 409-ФЗ)\n\n(Обозначение и наименование параграфа исключены - Федеральный закон от 28.11.2018 № 451-ФЗ)","article_title":"Статья 33. Споры, подлежащие передаче на рассмотрение третейского суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9445060a363d79695a01556fd1368fc518bde9dc62c0f90a04cfe47c85a5edc7"},{"code_id":"APK_RF","article_number":"330","version_date":"2002-07-24","article_text":"1. Вред, причиненный судебным приставом-исполнителем в результате неисполнения или ненадлежащего исполнения своих обязанностей по исполнению исполнительного листа, выданного арбитражным судом, подлежит возмещению в порядке, предусмотренном гражданским законодательством.\n\n2. Требование о возмещении вреда рассматривается арбитражным судом по общим правилам искового производства, предусмотренным настоящим Кодексом.","article_title":"Статья 330. Ответственность за неисполнение или ненадлежащее исполнение судебным приставом-исполнителем своих обязанностей","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"83af1233b1259733c0214c22ebd7891210a1248bbb8d92c2d80365a9dbb944dd"},{"code_id":"APK_RF","article_number":"331","version_date":"2002-07-24","article_text":"На лицо, виновное в утрате переданного ему на исполнение исполнительного листа, выданного арбитражным судом, арбитражный суд вправе наложить судебный штраф в порядке и в размере, установленных в главе 11 настоящего Кодекса.","article_title":"Статья 331. Ответственность за утрату исполнительного листа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9481dc6ecbc7f66c6e3b35307905df2d301c058287f517377f088f36ed8fff4f"},{"code_id":"APK_RF","article_number":"332","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\nПрезидент Российской Федерации                              В.Путин\n\nМосква, Кремль\n\n24 июля 2002 года","article_title":"Статья 332. Ответственность за неисполнение судебного акта","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"82417fc0f70e050e1abc9d1345ddc6e21c71ec6b4a820bcfe9ac5b696badd6e1"}]$law7d0018$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
